import { test, expect } from '@playwright/test';

test.describe('Bulk Delete Items from List', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    // Wait for the list to be visible
    await page.waitForLoadState('networkidle');
  });

  test('should select multiple items and bulk delete them', async ({ page }) => {
    // Get all checkboxes for list items
    const checkboxes = page.getByRole('checkbox', { name: /select item/i });

    // Select first three items
    const firstCheckbox = checkboxes.nth(0);
    const secondCheckbox = checkboxes.nth(1);
    const thirdCheckbox = checkboxes.nth(2);

    await firstCheckbox.check();
    await secondCheckbox.check();
    await thirdCheckbox.check();

    // Verify checkboxes are checked
    await expect(firstCheckbox).toBeChecked();
    await expect(secondCheckbox).toBeChecked();
    await expect(thirdCheckbox).toBeChecked();

    // Click bulk delete button
    const deleteButton = page.getByRole('button', { name: /delete selected/i });
    await deleteButton.click();

    // Confirm deletion in modal if present
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    if (await confirmButton.isVisible()) {
      await confirmButton.click();
    }

    // Verify items are deleted
    const remainingItems = page.getByRole('listitem');
    const initialCount = await checkboxes.count();
    const finalCount = await remainingItems.count();

    expect(finalCount).toBeLessThan(initialCount);
  });

  test('should show delete button only when items are selected', async ({ page }) => {
    const deleteButton = page.getByRole('button', { name: /delete selected/i });

    // Delete button should be disabled initially
    await expect(deleteButton).toBeDisabled();

    // Select an item
    const firstCheckbox = page.getByRole('checkbox', { name: /select item/i }).nth(0);
    await firstCheckbox.check();

    // Delete button should now be enabled
    await expect(deleteButton).toBeEnabled();

    // Uncheck the item
    await firstCheckbox.uncheck();

    // Delete button should be disabled again
    await expect(deleteButton).toBeDisabled();
  });

  test('should select all items with select-all checkbox', async ({ page }) => {
    // Click select-all checkbox
    const selectAllCheckbox = page.getByRole('checkbox', { name: /select all/i });
    await selectAllCheckbox.check();

    // Verify all item checkboxes are checked
    const itemCheckboxes = page.getByRole('checkbox', { name: /select item/i });
    const checkboxCount = await itemCheckboxes.count();

    for (let i = 0; i < checkboxCount; i++) {
      await expect(itemCheckboxes.nth(i)).toBeChecked();
    }

    // Click bulk delete
    const deleteButton = page.getByRole('button', { name: /delete selected/i });
    await deleteButton.click();

    // Confirm deletion
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    if (await confirmButton.isVisible()) {
      await confirmButton.click();
    }

    // Verify all items are deleted
    const remainingItems = page.getByRole('listitem');
    await expect(remainingItems).toHaveCount(0);
  });

  test('should display success message after bulk delete', async ({ page }) => {
    // Select items
    const checkboxes = page.getByRole('checkbox', { name: /select item/i });
    await checkboxes.nth(0).check();
    await checkboxes.nth(1).check();

    // Click delete button
    const deleteButton = page.getByRole('button', { name: /delete selected/i });
    await deleteButton.click();

    // Confirm deletion
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    if (await confirmButton.isVisible()) {
      await confirmButton.click();
    }

    // Verify success message appears
    const successMessage = page.getByText(/successfully deleted/i);
    await expect(successMessage).toBeVisible();
  });
});
